eFileExt' /t REG_DWORD /d '0' /f | Out-Null reg add 'HKU\WH_DEF\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' /v 'Hidden' /t REG_DWORD /d '1' /f | Out-Null reg add 'HKU\WH_DEF\Software\Microsoft\Windows\CurrentVersion\Explorer\CabinetState' /v 'FullPath' /t REG_DWORD /d '1' /f | Out-Null reg add 'HKU\WH_DEF\Software\Classes\CLSID\{86ca1aa0-34aa-4e8b-a509-50c905bae2a2}\InprocServer32' /ve /t REG_SZ /f | Out-Null reg add 'HKU\WH_DEF\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' /v 'LaunchTo' /t REG_DWORD /d '1' /f | Out-Null reg add 'HKU\WH_DEF\Software\Microsoft\Windows\CurrentVersion\Explorer' /v 'ShowRecent' /t REG_DWORD /d '0' /f | Out-Null reg add 'HKU\WH_DEF\Software\Microsoft\Windows\CurrentVersion\Explorer' /v 'ShowFrequent' /t REG_DWORD /d '0' /f | Out-Null reg add 'HKU\WH_DEF\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' /v 'ShowSyncProviderNotifications' /t REG_DWORD /d '0' /f | Out-Null reg add 'HKU\WH_DEF\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel' /v '{F02C1A0D-BE21-4350-88B0-7367FC96F89C}' /t REG_DWORD /d '0' /f | Out-Null Get-ChildItem -LiteralPath 'Registry::HKEY_USERS\WH_DEF\AppEvents\Schemes\Apps' -Recurse | Where-Object { $_.PSChildName -eq '.Current' } | ForEach-Object { Set-ItemProperty -LiteralPath $_.PSPath -Name '(default)' -Value '' } # Prevent OneDrive from reinstalling itself at first logon reg delete "HKU\WH_DEF\Software\Microsoft\Windows\CurrentVersion\Run" /v "OneDriveSetup" /f | Out-Null [GC]::Collect(); [GC]::WaitForPendingFinalizers(); Start-Sleep 1 reg unload HKU\WH_DEF | Out-Null
# .NET Framework 3.5 foreach ($d in (Get-PSDrive -PSProvider FileSystem)) { $p = Join-Path $d.Root 'sources\sxs'; if (Test-Path $p) { dism /online /enable-feature /featurename:NetFx3 /All /Source:$p /LimitAccess | Out-Null; break } }
# Commands reg add 'HKU\.DEFAULT\Control Panel\Keyboard' /v InitialKeyboardIndicators /t REG_SZ /d 2 /f | Out-Null Remove-WindowsCapability -Online -Name 'App.StepsRecorder~~~~0.0.1.0' | Out-Null Remove-WindowsCapability -Online -Name 'MathRecognizer~~~~0.0.1.0' | Out-Null Remove-WindowsCapability -Online -Name 'Browser.InternetExplorer~~~~0.0.11.0' | Out-Null Disable-WindowsOptionalFeature -Online -FeatureName 'MicrosoftWindowsPowerShellV2Root' -NoRestart | Out-Null Disable-WindowsOptionalFeature -Online -FeatureName 'SMB1Protocol' -NoRestart | Out-Null Stop-Process -Name OneDrive -Force; foreach ($p in "$env:SystemRoot\SysWOW64\OneDriveSetup.exe","$env:SystemRoot\System32\OneDriveSetup.exe") { if (Test-Path $p) { Start-Process $p '/uninstall' -Wait } } foreach ($n in 'DiagTrack','dmwappushservice') { $k = "HKLM:\SYSTEM\CurrentControlSet\Services\$n"; if (Test-Path $k) { Set-ItemProperty -Path $k -Name Start -Value 4 -Type DWord } } foreach ($n in 'diagnosticshub.standardcollector.service','WerSvc') { $k = "HKLM:\SYSTEM\CurrentControlSet\Services\$n"; if (Test-Path $k) { Set-ItemProperty -Path $k -Name Start -Value 4 -Type DWord } } foreach ($n in 'Fax') { $k = "HKLM:\SYSTEM\CurrentControlSet\Services\$n"; if (Test-Path $k) { Set-ItemProperty -Path $k -Name Start -Value 4 -Type DWord } } foreach ($n in 'RetailDemo','MapsBroker') { $k = "HKLM:\SYSTEM\CurrentControlSet\Services\$n"; if (Test-Path $k) { Set-ItemProperty -Path $k -Name Start -Value 4 -Type DWord } } foreach ($n in 'RemoteRegistry','RemoteAccess') { $k = "HKLM:\SYSTEM\CurrentControlSet\Services\$n"; if (Test-Path $k) { Set-ItemProperty -Path $k -Name Start -Value 4 -Type DWord } } foreach ($n in 'WpcMonSvc','SEMgrSvc') { $k = "HKLM:\SYSTEM\CurrentControlSet\Services\$n"; if (Test-Path $k) { Set-ItemProperty -Path $k -Name Start -Value 4 -Type DWord } } foreach ($n in 'PhoneSvc','SmsRouter','icssvc') { $k = "HKLM:\SYSTEM\CurrentControlSet\Services\$n"; if (Test-Path $k) { Set-ItemProperty -Path $k -Name Start -Value 4 -Type DWord } } foreach ($n in 'wisvc','WFDSConMgrSvc','lltdsvc') { $k = "HKLM:\SYSTEM\CurrentControlSet\Services\$n"; if (Test-Path $k) { Set-ItemProperty -Path $k -Name Start -Value 4 -Type DWord } } foreach ($n in 'WMPNetworkSvc') { $k = "HKLM:\SYSTEM\CurrentControlSet\Services\$n"; if (Test-Path $k) { Set-ItemProperty -Path $k -Name Start -Value 4 -Type DWord } } foreach ($n in 'SCardSvr','ScDeviceEnum','CertPropSvc') { $k = "HKLM:\SYSTEM\CurrentControlSet\Services\$n"; if (Test-Path $k) { Set-ItemProperty -Path $k -Name Start -Value 4 -Type DWord } } foreach ($n in 'lfsvc') { $k = "HKLM:\SYSTEM\CurrentControlSet\Services\$n"; if (Test-Path $k) { Set-ItemProperty -Path $k -Name Start -Value 4 -Type DWord } }
# Remove apps $apps = @('*CandyCrush*', '*TikTok*', '*Facebook*', '*Instagram*', 'Disney.*', 'Amazon.com.Amazon', 'AmazonVideo.PrimeVideo', 'SpotifyAB.SpotifyMusic', '4DF9E0F8.Netflix', '*LinkedIn*', '*Twitter*', '*Duolingo*', '*AdobeExpress*', '*Pinterest*', 'Microsoft.BingNews', 'Microsoft.BingWeather', 'Microsoft.BingSearch', 'Microsoft.GetHelp', 'Microsoft.Getstarted', 'Microsoft.MicrosoftOfficeHub', 'Microsoft.MicrosoftSolitaireCollection', 'Microsoft.People', 'Microsoft.WindowsFeedbackHub', 'Microsoft.WindowsMaps', 'Microsoft.YourPhone', 'Microsoft.Todos', 'Microsoft.PowerAutomateDesktop', 'Clipchamp.Clipchamp', 'MicrosoftTeams', 'MSTeams', 'Microsoft.OutlookForWindows', 'Microsoft.Copilot', 'Microsoft.Windows.DevHome', 'MicrosoftCorporationII.QuickAssist', 'Microsoft.549981C3F5F10', 'MicrosoftWindows.CrossDevice') foreach ($n in $apps) { Get-AppxPackage -AllUsers -Name $n | Remove-AppxPackage -AllUsers Get-AppxProvisionedPackage -Online | Where-Object { $_.DisplayName -like $n } | Remove-AppxProvisionedPackage -Online | Out-Null }
# One-time task: runs firstboot.ps1 as SYSTEM at the first sign-in (network, power, drivers) $task = @' <Task version="1.2" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task"> <Triggers><LogonTrigger><Enabled>true</Enabled></LogonTrigger></Triggers> <Principals><Principal id="Author"><UserId>S-1-5-18</UserId><RunLevel>HighestAvailable</RunLevel></Principal></Principals> <Settings><MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy><DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries><StopIfGoingOnBatteries>false</StopIfGoingOnBatteries><ExecutionTimeLimit>PT3H</ExecutionTimeLimit><Enabled>true</Enabled></Settings> <Actions Context="Author"><Exec><Command>powershell.exe</Command><Arguments>-NoProfile -ExecutionPolicy Bypass -File "C:\ProgramData\WinTweaks\firstboot.ps1"</Arguments></Exec></Actions> </Task> '@ Register-ScheduledTask -TaskName 'WinTweaks-FirstBoot' -Xml $task -Force | Out-Null
Stop-Transcript | Out-Null

$ErrorActionPreference = 'SilentlyContinue' # Runs once as SYSTEM at the first sign-in (scheduled task WinTweaks-FirstBoot), whatever the account type. # The task can also start for the temporary OOBE account: wait until OOBE is over and a real account is signed in. for ($i = 0; $i -lt 360; $i++) { $u = (Get-CimInstance Win32_ComputerSystem).UserName if ((Get-ItemProperty -LiteralPath 'HKLM:\SYSTEM\Setup').OOBEInProgress -ne 1 -and $u -and $u -notmatch 'defaultuser\d') { break } Start-Sleep 10 } try { [IO.File]::Open("$env:ProgramData\WinTweaks\firstboot.lock", 'CreateNew').Close() } catch { exit } Unregister-ScheduledTask -TaskName 'WinTweaks-FirstBoot' -Confirm:$false Start-Transcript -Path "$env:ProgramData\WinTweaks\firstboot.log" -Append | Out-Null
# Turn the network adapters back on (they were disabled during setup) Get-NetAdapter | Enable-NetAdapter -Confirm:$false
# Wi-Fi profile if (Get-Service WlanSvc -ErrorAction SilentlyContinue) { for ($i = 0; $i -lt 20 -and (Get-Service WlanSvc).Status -ne 'Running'; $i++) { Start-Sleep 2 } $wp = Join-Path $env:ProgramData 'WinTweaks\wifi-profile.xml' $wx = @' <?xml version="1.0"?> <WLANProfile xmlns="http://www.microsoft.com/networking/WLAN/profile/v1"> <name>MyWiFi</name> <SSIDConfig><SSID><hex>4D7957694669</hex><name>MyWiFi</name></SSID><nonBroadcast>false</nonBroadcast></SSIDConfig> <connectionType>ESS</connectionType> <connectionMode>auto</connectionMode> <MSM><security> <authEncryption><authentication>WPA2PSK</authentication><encryption>AES</encryption><useOneX>false</useOneX></authEncryption> <sharedKey><keyType>passPhrase</keyType><protected>false</protected><keyMaterial>YourWiFiPassword</keyMaterial></sharedKey> </security></MSM> </WLANProfile> '@ Set-Content -LiteralPath $wp -Value $wx -Encoding UTF8 netsh wlan add profile filename="$wp" user=all | Out-Null Remove-Item -LiteralPath $wp -Force $wn = 'MyWiFi' netsh wlan connect name="$wn" | Out-Null $m = [regex]::Match($wx, '<keyMaterial>.*?</keyMaterial>') if ($m.Success) { $files = @($PSCommandPath) + @(Get-ChildItem 'C:\Windows\Panther' -Recurse -File -Filter 'unattend*.xml' | ForEach-Object { $_.FullName }) foreach ($f in $files) { if ($f -and (Test-Path -LiteralPath $f)) { $t = [IO.File]::ReadAllText($f).Replace($m.Value, '<keyMaterial>********</keyMaterial>'); [IO.File]::WriteAllText($f, $t, (New-Object Text.UTF8Encoding $false)) } } } }
# DNS $dns = @('1.1.1.1', '1.0.0.1') foreach ($a in Get-NetAdapter -Physical) { Set-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ServerAddresses $dns }
# Disable IPv6 foreach ($a in Get-NetAdapter -Physical) { Disable-NetAdapterBinding -Name $a.Name -ComponentID ms_tcpip6 }
# Private network profile for ($i = 0; $i -lt 30 -and -not (Get-NetConnectionProfile); $i++) { Start-Sleep 2 } Get-NetConnectionProfile | Where-Object { $_.NetworkCategory -eq 'Public' } | Set-NetConnectionProfile -NetworkCategory Private
# Power and other system settings $o = powercfg -duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61; if ($o -match '([0-9a-fA-F-]{36})') { powercfg -setactive $Matches[1] } powercfg /hibernate off powercfg /change monitor-timeout-ac 0 powercfg /change monitor-timeout-dc 0 powercfg /change standby-timeout-ac 0 powercfg /change standby-timeout-dc 0
# NVIDIA driver (silent installer copied to this path beforehand) $s = 'C:\Drivers\NVIDIA\setup.exe' if (Test-Path $s) { Start-Process $s -ArgumentList '-s','-noreboot' -Wait }
Stop-Transcript | Out-Null
